#!/usr/bin/env sh
# fetch opentransportdata.swiss (NAP) — national combined GTFS: SBB rail + all cantonal/city operators (VBZ Zurich, TPG Geneva, BVB Basel, BLT, BERNMOBIL, PostAuto, etc.) (CH) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://data.opentransportdata.swiss/dataset/3d2c18f9-9ef1-463f-a249-5c67604efd74/resource/940f970d-1ab6-4320-9c7e-f8dc5a2af48d/download/gtfs_fp2026_20260729.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
